/**
 * migrate-curated-overlay.mjs — One-time migration helper.
 *
 * Reads the OLD hand-curated schools.js (before auto-generation) and emits
 * app/src/data/curatedOverlay.js — a JSON map keyed by skill id, containing
 * the hand-curated values that don't come from SKILL.md frontmatter:
 *
 *   { displayName, status, note, combos }
 *
 * Run once:  node app/scripts/migrate-curated-overlay.mjs
 *
 * After running, the generated registry will pick up the curated overlay
 * and merge it with the auto-generated values, so existing skills keep
 * their grimoire-themed names and curated metadata.
 */

import { promises as fs } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { APP_DIR } from '../../scripts/lib/constants.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const OLD_SCHOOLS = path.join(APP_DIR, 'src', 'data', 'schools.legacy.js');
const OVERLAY_OUT = path.join(APP_DIR, 'src', 'data', 'curatedOverlay.js');

async function main() {
  if (!(await exists(OLD_SCHOOLS))) {
    // Try to fetch from git history
    console.log('[migrate] no legacy file at', OLD_SCHOOLS);
    console.log('[migrate] attempting to fetch from git history...');
    try {
      const { execSync } = await import('child_process');
      const { REPO_ROOT } = await import('../../scripts/lib/constants.mjs');
      const fetched = execSync('git show HEAD:app/src/data/schools.js', {
        cwd: REPO_ROOT,
        encoding: 'utf8',
      });
      await fs.writeFile(OLD_SCHOOLS, fetched, 'utf8');
      console.log('[migrate] fetched from git, wrote', OLD_SCHOOLS);
    } catch (err) {
      console.error('[migrate] could not fetch from git:', err.message);
      process.exit(1);
    }
  }
  const src = await fs.readFile(OLD_SCHOOLS, 'utf8');
  // Extract all spell entries
  // Format: {name:'Foo',skill:'foo-spell',effect:'...',status:'Proven',combos:[...],note:'...'}
  // Each field is optional and can appear in any order. Use a separate
  // scan for each to keep the regex simple and order-flexible.
  const startRe = /\{name:'([^']+)',skill:'([^']+)',effect:'((?:[^'\\]|\\.)*)'/g;
  const overlay = {};
  for (const start of src.matchAll(startRe)) {
    const startIdx = start.index + start[0].length;
    // Find the matching closing brace — find the next `},` or `}` after start
    const rest = src.slice(startIdx);
    // Find the closing brace at the same nesting level. Each spell is
    // a single brace pair; the effect field ends at the first `',` and
    // everything up to the next `}` is field values.
    const close = rest.indexOf('}');
    if (close === -1) continue;
    const fieldsStr = rest.slice(0, close);
    const status = (fieldsStr.match(/,status:'([^']*)'/) || [])[1];
    const note = (fieldsStr.match(/,note:'((?:[^'\\]|\\.)*)'/) || [])[1];
    const combosStr = (fieldsStr.match(/,combos:\[([^\]]*)\]/) || [])[1];
    const entry = { displayName: start[1] };
    if (status) entry.status = status;
    if (note) entry.note = note;
    if (combosStr) {
      entry.combos = combosStr.split(',').map(s => s.trim().replace(/^['"]|['"]$/g, '')).filter(Boolean);
    }
    overlay[start[2]] = entry;
  }
  console.log(`[migrate] extracted ${Object.keys(overlay).length} curated entries`);

  // Also extract school theming (id, real, name, desc) per topic.
  // Schools are spread across multiple lines:
  //   {id:'debugging',real:'Debugging',
  //    name:'School of Remediation',
  //    desc:'Incantations to banish bugs and restore order to broken code.',
  //    spells:[...
  const schoolRe = /id:'([^']+)',real:'([^']*)',\s*name:'([^']*)',\s*desc:'([^']*)'/g;
  const schools = {};
  for (const m of src.matchAll(schoolRe)) {
    const [, id, real, name, desc] = m;
    schools[id] = { id, real, name, desc };
  }
  console.log(`[migrate] extracted ${Object.keys(schools).length} school themes`);

  // Write the overlay file
  const content = `// AUTO-GENERATED by scripts/migrate-curated-overlay.mjs
// Hand-curated per-spell metadata preserved from the legacy schools.js.
// Keys are skill ids. Use this overlay to override auto-generated values.

export const CURATED_OVERLAY = ${JSON.stringify(overlay, null, 2)};

export const CURATED_SCHOOLS = ${JSON.stringify(schools, null, 2)};
`;
  await fs.writeFile(OVERLAY_OUT, content, 'utf8');
  console.log(`[migrate] wrote ${path.relative(process.cwd(), OVERLAY_OUT)}`);
}

async function exists(p) {
  try { await fs.access(p); return true; } catch { return false; }
}

main().catch(err => {
  console.error('[migrate] failed:', err);
  process.exit(1);
});
